/**
 * generator.js
 * -------------------------------------------------------------------------
 * Pure password-generation logic, character classification, and qualitative
 * strength classification for PassFuse.
 * Depends on: config (character sets + limits) and random (Web Crypto primitives).
 *
 * GENERATION & CLASSIFICATION MODEL
 * 1. Uniform Rejection Sampling:
 *    Let C be the set of enabled character categories, each with disjoint
 *    character pool P_i, and let P = U_{i in C} P_i be the combined pool.
 *    A candidate of length L is generated by drawing L characters independently
 *    and uniformly from P via `pick(P)`. The candidate is accepted iff it
 *    contains at least one character from every enabled category i in C.
 *    Because every valid string in V subset P^L has identical probability on
 *    each independent trial, conditioning on acceptance yields an exact
 *    uniform distribution over V with zero positional or frequency bias.
 *
 * 2. Qualitative Strength Classification:
 *    Evaluates the generated password configuration across actual length,
 *    enabled category diversity, and effective character set properties (such
 *    as non-numeric diversity and symbol/mixed-case inclusion) to assign one of
 *    four qualitative levels: WEAK, FAIR, STRONG, or VERY STRONG.
 * -------------------------------------------------------------------------
 */
(function (PG) {
  "use strict";

  const SETS = PG.config.SETS;
  const STRENGTH = PG.config.STRENGTH;
  const MIN_LENGTH = PG.config.MIN_LENGTH;
  const MAX_LENGTH = PG.config.MAX_LENGTH;
  const MAX_REJECTION_ATTEMPTS = PG.config.MAX_REJECTION_ATTEMPTS;
  const pick = PG.random.pick;

  /**
   * Validate and resolve the per-category character pools for `options`.
   * @param {string[]} options Enabled category keys.
   * @returns {{ pools: string[], combined: string }}
   */
  function resolveCategoryPools(options) {
    if (!Array.isArray(options) || options.length === 0) {
      throw new Error("NO_OPTIONS");
    }
    if (new Set(options).size !== options.length) {
      throw new Error("INVALID_OPTIONS");
    }
    const pools = [];
    let combined = "";
    for (let i = 0; i < options.length; i++) {
      const option = options[i];
      if (typeof option !== "string" || !Object.hasOwn(SETS, option)) {
        throw new Error("INVALID_OPTIONS");
      }
      const pool = SETS[option];
      if (pool.length === 0) {
        throw new Error("EMPTY_CATEGORY");
      }
      pools.push(pool);
      combined += pool;
    }
    return { pools: pools, combined: combined };
  }

  /**
   * Concatenate the character pools for the selected options.
   * @param {string[]} options
   * @returns {string}
   */
  function poolFor(options) {
    return resolveCategoryPools(options).combined;
  }

  /**
   * Check whether `candidate` contains at least one character from every pool
   * in `pools`.
   * @param {string} candidate
   * @param {string[]} pools
   * @returns {boolean}
   */
  function satisfiesAllCategories(candidate, pools) {
    for (let i = 0; i < pools.length; i++) {
      const categoryPool = pools[i];
      let found = false;
      for (let j = 0; j < candidate.length; j++) {
        if (categoryPool.includes(candidate[j])) {
          found = true;
          break;
        }
      }
      if (!found) return false;
    }
    return true;
  }

  /**
   * Generate a password of `length` characters using uniform cryptographic
   * rejection sampling over the valid category-constrained output space.
   * @param {number} length Requested length (MIN_LENGTH..MAX_LENGTH).
   * @param {string[]} options Enabled category keys.
   * @returns {string}
   */
  function generatePassword(length, options) {
    if (
      !Number.isSafeInteger(length) ||
      length < MIN_LENGTH ||
      length > MAX_LENGTH
    ) {
      throw new RangeError("INVALID_LENGTH");
    }
    const resolved = resolveCategoryPools(options);
    const pools = resolved.pools;
    const combined = resolved.combined;
    if (length < pools.length) {
      throw new RangeError("LENGTH_TOO_SHORT");
    }

    for (let attempt = 0; attempt < MAX_REJECTION_ATTEMPTS; attempt++) {
      let candidate = "";
      for (let i = 0; i < length; i++) {
        candidate += pick(combined);
      }
      if (pools.length === 1 || satisfiesAllCategories(candidate, pools)) {
        return candidate;
      }
    }

    throw new Error("REJECTION_LIMIT_EXCEEDED");
  }

  /**
   * Classify a single character into its display category (`letter`, `number`,
   * or `symbol`) for category-aware color rendering.
   * @param {string} ch Single character.
   * @returns {"letter"|"number"|"symbol"}
   */
  function classifyCharacter(ch) {
    if (typeof ch !== "string" || ch.length === 0) {
      return "letter";
    }
    const c = ch[0];
    if (SETS.numbers.includes(c)) {
      return "number";
    }
    if (SETS.symbols.includes(c)) {
      return "symbol";
    }
    return "letter";
  }

  /**
   * Qualitative password-strength classification based on actual length,
   * enabled categories, effective character set composition, and generation
   * constraints. Does not expose or rely on numeric scores or bit counts.
   *
   * Classification tiers:
   * - WEAK (1 bar): Short length (< 10), digits-only under 16 chars, or
   *   single-category passwords under 12 chars.
   * - FAIR (2 bars): Moderate length (10–11 with 2+ categories, or 12–15 with
   *   a single non-numeric category, or 16+ digits-only).
   * - STRONG (3 bars): Solid length and diversity (12–15 with 2+ categories,
   *   or 16+ with 1–2 categories, or 16–17 with 3 categories).
   * - VERY STRONG (4 bars): Long, multi-category credentials with broad
   *   character-set coverage (16+ with all 4 categories, 18+ with 3+
   *   categories, or 22+ with at least 2 categories including letters or
   *   symbols).
   *
   * @param {number} length Password length.
   * @param {string[]} options Enabled category keys.
   * @returns {{ level: string, bars: number, label: string }}
   */
  function classifyStrength(length, options) {
    if (
      !Number.isSafeInteger(length) ||
      length < MIN_LENGTH ||
      length > MAX_LENGTH
    ) {
      return STRENGTH[0];
    }
    let resolved;
    try {
      resolved = resolveCategoryPools(options);
    } catch {
      return STRENGTH[0];
    }
    const categoryCount = resolved.pools.length;
    if (length < categoryCount) {
      return STRENGTH[0];
    }

    const onlyNumbers = categoryCount === 1 && options[0] === "numbers";
    const hasSymbols = options.includes("symbols");
    const hasBothCases =
      options.includes("uppercase") && options.includes("lowercase");

    // Tier 1: WEAK
    if (
      length < 10 ||
      (onlyNumbers && length < 16) ||
      (categoryCount === 1 && length < 12)
    ) {
      return STRENGTH[0];
    }

    // Tier 4: VERY STRONG
    if (
      (length >= 16 && categoryCount === 4) ||
      (length >= 18 && categoryCount >= 3) ||
      (length >= 22 && categoryCount >= 2 && (hasSymbols || hasBothCases))
    ) {
      return STRENGTH[3];
    }

    // Tier 3: STRONG
    if (
      (length >= 12 && categoryCount >= 3) ||
      (length >= 13 && categoryCount === 2 && (hasSymbols || hasBothCases)) ||
      (length >= 15 && categoryCount >= 2) ||
      (length >= 18 && !onlyNumbers)
    ) {
      return STRENGTH[2];
    }

    // Tier 2: FAIR
    return STRENGTH[1];
  }

  PG.generator = Object.freeze({
    poolFor: poolFor,
    generatePassword: generatePassword,
    classifyCharacter: classifyCharacter,
    classifyStrength: classifyStrength,
    estimateStrength: classifyStrength,
  });
})((window.PasswordGen = window.PasswordGen || {}));
